import copy
import json


class JsonWriter(object):
    def __init__(self, dict_to_write):
        self.dict_to_write = copy.deepcopy(dict_to_write)

    def write_to_file(self, file_path):
        with open(file_path, "w") as json_handler:
            json_handler.write(json.dumps(self.dict_to_write, sort_keys=True, indent=4, separators=(',', ': ')))
